using System.Runtime.InteropServices;

namespace LessonApp;

public static class RuntimeReport
{
    public static string AppAssemblyName()
    {
        return typeof(RuntimeReport).Assembly.GetName().Name!;
    }

    public static string[] OutputFolderFiles()
    {
        return Directory.GetFiles(AppContext.BaseDirectory).Select(Path.GetFileName).ToArray()!;
    }

    public static bool IsInSharedFramework(Type type)
    {
        return type.Assembly.Location.StartsWith(RuntimeEnvironment.GetRuntimeDirectory(), StringComparison.OrdinalIgnoreCase);
    }
}

