public static class Counters
{
    public static Func<int> Make(int start, int step)
    {
        int next = start;
        return () =>
        {
            int value = next;
            next += step;
            return value;
        };
    }
}

Challenge: thermostat.Thermostat.cs:
namespace LessonApp;

public class Thermostat(int limit)
{
    public int Limit { get; } = limit;
    public int Temperature { get; private set; } = 20;

    public event EventHandler<int>? TemperatureChanged;
    public event EventHandler? Overheated;

    public void Set(int value)
    {
        if (value == Temperature) return;
        bool wasOk = Temperature <= Limit;
        Temperature = value;
        TemperatureChanged?.Invoke(this, value);
        if (wasOk && value > Limit) Overheated?.Invoke(this, EventArgs.Empty);
    }
}

