public class Checkout(ILogger<Checkout> logger)
{
    public void Pay(decimal amount)
    {
        if (amount <= 0)
        {
            logger.LogError("Rejected payment of {Amount}", amount);
            return;
        }
        logger.LogInformation("Paid {Amount}", amount);
        if (amount > 1000)
            logger.LogWarning("Large payment of {Amount}", amount);
    }
}

